<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
require ROOT.'/app/Core/Router.php';
require ROOT.'/app/Core/View.php';
$checks=0;
function automation_check(bool $ok,string $label): void { global $checks; if (!$ok) throw new RuntimeException($label); $checks++; }
function automation_rejects(callable $fn,string $label): void { try { $fn(); } catch (InvalidArgumentException $e) { automation_check(true,$label); return; } throw new RuntimeException($label); }
set_error_handler(static function (int $severity,string $message,string $file,int $line): never { throw new ErrorException($message,0,$severity,$file,$line); });
$file=sys_get_temp_dir().'/lifeos-automation-'.bin2hex(random_bytes(6)).'.db';
try {
    Db::init($file); $modules=Modules::discover(ROOT.'/app/Modules');
    $dirs=array_merge([ROOT.'/app/Core/migrations'],array_map(fn($m)=>$m['path'].'/migrations',$modules));
    Migrator::run($dirs); Migrator::run($dirs);
    automation_check(Db::all('SELECT * FROM automation_rules')===[],'No automations enabled without consent');
    $now=new DateTimeImmutable('2026-11-08 07:00:00',new DateTimeZone('Asia/Colombo'));
    $rule=AutomationService::save(null,'Private <routine>','daily',['time'=>'07:00'],[['type'=>'notify','title'=>'Hello <script>','body'=>'Amma & family']]);
    automation_check(AutomationService::tick($now)['ran']===0,'New rules start paused');
    AutomationService::toggle($rule,true);
    automation_check(AutomationService::tick($now->modify('-1 minute'))['ran']===0,'Rule waits for local scheduled time');
    automation_check(AutomationService::tick($now)['ran']===1,'Enabled local schedule runs');
    automation_check(AutomationService::tick($now)['ran']===0 && count(Db::all('SELECT * FROM automation_messages'))===1,'Repeated ticks have exactly one effect per slot');
    $message=AutomationService::alerts()[0];
    automation_check(strlen($message['id'])===64 && $message['title']==='Hello <script>','Notification adapter supplies stable IDs and original text');
    $foreign=Db::run("INSERT INTO automation_rules(profile_id,name,enabled,trigger,conditions,actions) VALUES ('different-profile','Other profile',1,'daily',?,?)",[json_encode(['time'=>'07:00']),json_encode([['type'=>'notify','title'=>'Other family member','body'=>'Private']])]);
    automation_rejects(fn()=>AutomationService::rule($foreign),'Rules from another profile cannot be opened');
    automation_check(AutomationService::tick($now)['ran']===0 && !array_filter(AutomationService::alerts(),fn($a)=>$a['title']==='Other family member'),'Ticks and alerts exclude another profile');
    AutomationService::tick($now->modify('+3 days'));
    automation_check(count(Db::all('SELECT * FROM automation_runs'))===2,'Missed days are not backfilled');
    automation_rejects(fn()=>AutomationService::save(null,'Bad','daily',[],[['type'=>'shell','body'=>'anything']],true),'Arbitrary shell action rejected');
    automation_rejects(fn()=>AutomationService::save(null,'Bad','daily',['time'=>'25:00'],[['type'=>'morning_brief']],true),'Invalid local schedule rejected');
    automation_rejects(fn()=>AutomationService::save(null,'Bad','daily',['weekdays'=>[]],[['type'=>'morning_brief']],true),'Empty weekday condition rejected');
    automation_rejects(fn()=>AutomationService::save(null,'Bad','daily',[],[['type'=>'weekly_report']],true),'Invalid report trigger/action combination rejected');
    automation_rejects(fn()=>AutomationService::save(null,'Bad','daily',['script'=>'no'],[['type'=>'morning_brief']],true),'Unknown condition rejected');
    $conditional=AutomationService::save(null,'Conditional','daily',['time'=>'07:00','min_open_tasks'=>10],[['type'=>'notify','title'=>'Should skip','body'=>'No enough open tasks']],true);
    automation_check(AutomationService::tick($now)['skipped']===1 && Db::one('SELECT status FROM automation_runs WHERE rule_id=?',[$conditional])['status']==='skipped','Unmet conditions are visible skipped runs');
    AutomationService::toggle($rule,false); AutomationService::toggle($conditional,false);
    $failed=AutomationService::save(null,'Atomic failure','daily',['time'=>'07:00'],[['type'=>'morning_brief'],['type'=>'notify','title'=>'Deliberate failure','body'=>'Test only']],true);
    Db::exec("CREATE TRIGGER automation_test_failure BEFORE INSERT ON automation_messages WHEN NEW.title='Deliberate failure' BEGIN SELECT RAISE(ABORT,'Test action failure'); END");
    $before=count(Db::all('SELECT * FROM automation_messages'));
    $oldLog=ini_get('error_log'); ini_set('error_log',$file.'.log');
    $failureResult=AutomationService::tick($now); ini_set('error_log',$oldLog);
    automation_check($failureResult['failed']===1 && count(Db::all('SELECT * FROM automation_messages'))===$before,'Failed second action rolls back first action and writes no partial messages');
    automation_check(Db::one('SELECT status FROM automation_runs WHERE rule_id=?',[$failed])['status']==='failed' && AutomationService::tick($now)['failed']===0,'Failed slot is recorded visibly and not retried endlessly');
    Db::exec('DROP TRIGGER automation_test_failure'); AutomationService::toggle($failed,false);
    foreach ([7,3,1,0,2] as $days) Db::run('INSERT INTO tasks(title,due) VALUES (?,?)',['Due '.$days,$now->modify('+'.$days.' days')->format('Y-m-d')]);
    $done=Db::run("INSERT INTO tasks(title,due,status,completed_at) VALUES ('Already done',?,'done',?)",[$now->format('Y-m-d'),'2026-11-02 03:00:00']);
    $deadline=AutomationService::install('deadlines');
    AutomationService::save($deadline,'My early countdown','deadline',['time'=>'06:30'],[['type'=>'deadline_reminder']],false);
    automation_check(AutomationService::install('deadlines')===$deadline && AutomationService::install('deadlines')===$deadline && count(Db::all("SELECT * FROM automation_rules WHERE profile_id='default' AND template_key='deadlines'"))===1,'Repeated starter activation reuses one rule per template and profile');
    $savedStarter=AutomationService::rule($deadline);
    automation_check($savedStarter['enabled']===1 && $savedStarter['name']==='My early countdown' && json_decode($savedStarter['conditions'],true)['time']==='06:30','Re-enabling a starter preserves custom name and schedule');
    automation_check(AutomationService::tick($now)['ran']===1,'Deadline template runs after explicit enable');
    $deadlineRun=Db::one('SELECT id FROM automation_runs WHERE rule_id=?',[$deadline])['id'];
    $messages=Db::all('SELECT * FROM automation_messages WHERE run_id=?',[$deadlineRun]);
    automation_check(count($messages)===4 && !array_filter($messages,fn($m)=>str_contains($m['body'],'Already done') || str_contains($m['body'],'Due 2')),'Ladder sends only 7/3/1/0 day unfinished deadlines');
    automation_check(AutomationService::install('deadlines')===$deadline && AutomationService::tick($now)['ran']===0 && count(Db::all('SELECT * FROM automation_messages WHERE run_id=?',[$deadlineRun]))===4,'Reactivating an already-run starter does not repeat its deadline notifications');
    AutomationService::toggle($deadline,false);
    $weekly=AutomationService::save(null,'Review','weekly',['time'=>'18:00','weekdays'=>[7]],[['type'=>'weekly_report']],true);
    Db::run("INSERT INTO tasks(title,status,completed_at) VALUES ('Boundary inside','done','2026-10-25 18:30:00')");
    Db::run("INSERT INTO tasks(title,status,completed_at) VALUES ('Boundary outside','done','2026-11-01 18:30:00')");
    $account=(int)Db::one('SELECT id FROM accounts ORDER BY id LIMIT 1')['id']; $category=(int)Db::one('SELECT id FROM expense_categories ORDER BY id LIMIT 1')['id'];
    Db::run('INSERT INTO expenses(date,category_id,account_id,amount,note) VALUES (?,?,?,?,?)',['2026-10-29',$category,$account,125.25,'Actual record']);
    Db::run("INSERT INTO income(date,source,amount,type) VALUES ('2026-10-28','Real income',1000,'other')");
    $habit=Db::run("INSERT INTO planner_habits(title) VALUES ('Study')"); Db::run("INSERT INTO planner_habit_checks(habit_id,date) VALUES (?,'2026-10-30')",[$habit]);
    Db::run("INSERT INTO focus_sessions(subject,kind,target_minutes,status,elapsed_seconds,completed_at) VALUES ('Study','study',25,'complete',1500,'2026-10-29 03:00:00')");
    automation_check(AutomationService::tick($now->setTime(18,0))['ran']===1,'Weekly report respects selected local weekday/time');
    $report=AutomationService::reportById((int)Db::one('SELECT id FROM automation_reports ORDER BY id DESC LIMIT 1')['id']);
    automation_check($report['starts_on']==='2026-10-26' && $report['ends_before']==='2026-11-02','Weekly report covers previous complete Monday through Sunday');
    automation_check($report['summary']['tasks_done']===1,'Completed task boundaries use Asia/Colombo converted to UTC');
    automation_check($report['summary']['income']===1000 && $report['summary']['expenses']===125.25 && $report['summary']['habit_checkins']===1 && $report['summary']['focus_minutes']===25,'Report uses actual recorded money, habits and completed study');
    $monthly=AutomationService::install('monthly');
    automation_check(AutomationService::tick(new DateTimeImmutable('2026-11-02 10:00:00+05:30'))['ran']===0,'Monthly rules wait for first day');
    AutomationService::toggle($weekly,false);
    automation_check(AutomationService::tick(new DateTimeImmutable('2026-11-01 08:00:00+05:30'))['ran']===1,'Monthly summary runs on first day');
    $month=AutomationService::reportById((int)Db::one('SELECT id FROM automation_reports ORDER BY id DESC LIMIT 1')['id']);
    automation_check($month['starts_on']==='2026-10-01' && $month['ends_before']==='2026-11-01' && $month['summary']['expenses']===125.25,'Monthly report covers previous complete month');
    $_SESSION=['csrf'=>'test-token']; $_SERVER['HTTP_HX_REQUEST']='true'; $_SERVER['REQUEST_URI']='/automation';
    $router=new Router(); (require ROOT.'/app/Modules/Automation/routes.php')($router);
    ob_start(); $router->dispatch('GET','/automation'); $html=ob_get_clean();
    automation_check(str_contains($html,'Private &lt;routine&gt;') && !str_contains($html,'Private <routine>'),'Automation page escapes user content');
    $multi=AutomationService::save(null,'Multiple actions','daily',['time'=>'07:00'],[['type'=>'morning_brief'],['type'=>'notify','title'=>'Second action','body'=>'Keep this message']],false);
    $_GET=['edit'=>(string)$multi];
    ob_start(); $router->dispatch('GET','/automation'); $html=ob_get_clean(); $_GET=[];
    automation_check(str_contains($html,'name="actions[1][type]"') && str_contains($html,'value="Second action"') && str_contains($html,'Keep this message'),'Editing a multi-action rule exposes every saved action and its text');
    $_POST=['id'=>(string)$multi,'name'=>'Edited multiple actions','trigger'=>'daily','time'=>'08:15','weekdays'=>['1','2','3','4','5','6','7'],'min_open_tasks'=>'0','actions'=>[['type'=>'morning_brief','title'=>'','body'=>''],['type'=>'notify','title'=>'Second action','body'=>'Keep this message'],['type'=>'','title'=>'','body'=>'']]];
    ob_start(); $router->dispatch('POST','/automation/rules'); ob_end_clean();
    $edited=AutomationService::rule($multi);
    automation_check($edited['name']==='Edited multiple actions' && json_decode($edited['conditions'],true)['time']==='08:15' && json_decode($edited['actions'],true)===[['type'=>'morning_brief'],['type'=>'notify','title'=>'Second action','body'=>'Keep this message']],'Builder preserves all actions when editing name or schedule and discards empty optional slots');
    $_POST['actions'][2]=['type'=>'notify','title'=>'Duplicate','body'=>'Should reject'];
    automation_rejects(function () use ($router): void { ob_start(); try { $router->dispatch('POST','/automation/rules'); } finally { ob_end_clean(); } },'Builder rejects duplicate action types');
    automation_check(AutomationService::rule($multi)===$edited,'Rejected builder update preserves the complete saved rule');
    if (class_exists('PersonaService')) {
        PersonaService::apply('school');
        // School persona keeps Planner enabled and turns Salary off.
        $after=AutomationService::save(null,'School weekly','weekly',['time'=>'18:00','weekdays'=>[7]],[['type'=>'weekly_report']],true);
        AutomationService::tick($now->modify('+7 days')->setTime(18,0));
        $school=AutomationService::reportById((int)Db::one('SELECT id FROM automation_reports ORDER BY id DESC LIMIT 1')['id']);
        automation_check($school['summary']['income']===null && $school['summary']['expenses']===null,'Disabled money module is excluded from reports');
        Db::run("UPDATE modules SET enabled=0 WHERE profile_id='default' AND module_id='Automation'");
        automation_check(AutomationService::tick($now->modify('+14 days')->setTime(18,0))['ran']===0 && AutomationService::alerts()===[],'Disabling automations stops execution and reminder exposure');
    }
    Db::close(); Db::init($file); Migrator::run($dirs);
    automation_check(count(Db::all('SELECT * FROM automation_runs'))>0,'Run ledger persists across database reopen and repeat migration');
} finally {
    Db::close(); foreach ([$file,$file.'-wal',$file.'-shm',$file.'.log'] as $temporary) if (is_file($temporary)) unlink($temporary);
    restore_error_handler();
}
echo "$checks automation checks passed.\n";
